 const queue=Array.isArray(g.hsQueue)?g.hsQueue:[];g.hsQueue=queue;const final=g.age===17;
 if(final){h.finished=true;h.graduated=true;g.hsQueue.push({type:'graduation',title:'High school graduation',text:`You have completed Grade 12. Your final cumulative GPA is ${h.gpa.toFixed(2)}. Your school record, activities, and college decisions shaped the next step.`,button:'Continue'});}
 const pool=HS_EVENTS.filter((e,i)=>!h.eventsSeen.includes(i));const eventIndex=pool.length?HS_EVENTS.indexOf(P(pool)):R(0,HS_EVENTS.length-1);h.eventsSeen.push(eventIndex);g.hsQueue.push({type:'event',data:HS_EVENTS[eventIndex]});if(final){const pool2=HS_EVENTS.filter((e,i)=>!h.eventsSeen.includes(i));const e2=pool2.length?P(pool2):P(HS_EVENTS);g.hsQueue.push({type:'event',data:e2});}
