function hsApplyEventChoice(ev,choice){const h=hsEnsure();if(choice.fx)A(choice.fx,`${choice.result||'You made your choice.'}`);else L(choice.result||'You made your choice.');if(choice.subject&&h.current&&h.current.subjects[choice.subject])h.current.subjects[choice.subject].score=cl(h.current.subjects[choice.subject].score+(choice.score||0),0,100);if(choice.teacher)h.teacher.bond=cl(h.teacher.bond+choice.teacher,0,100);if(choice.peer&&h.classmates.length){const peer=P(h.classmates);peer.bond=cl(peer.bond+choice.peer,0,100);if(peer.friendId){const r=g.rel.find(z=>z.id===peer.friendId&&z.alive);if(r)r.bond=peer.bond;}}if(choice.club&&h.club)h.club.performance=cl(h.club.performance+choice.club,0,100);if(choice.family&&g.rel){g.rel.filter(r=>r.alive&&(r.role==='Mother'||r.role==='Father'||r.role==='Parent')).forEach(r=>r.bond=cl(r.bond+choice.family,0,100));}if(choice.prepResearch)h.prep.research=cl(h.prep.research+choice.prepResearch,0,5);if(choice.prepEssay)h.prep.essays=cl(h.prep.essays+choice.prepEssay,0,2);hsRecalcGPA();}
function hsChooseEvent(i){const p=g.hsPopup;if(!p||p.type!=='event')return;const ev=p.data,choice=ev.choices[i];if(!choice)return;const cost=choice.fx&&Number(choice.fx.m)<0?-Number(choice.fx.m):0;if(cost>g.cash)return toast(`You need ${loc(cost)} for that choice.`);g.hsPopup=null;hsApplyEventChoice(ev,choice);hsNextPopup();}
