function hsShowNext(){if(!g.hsPopup&&Array.isArray(g.hsQueue)&&g.hsQueue.length)g.hsPopup=g.hsQueue.shift();if(g.hsPopup)draw();}
function hsReportView(r){return `<div class=card><div class=t>Grade ${r.grade} report card</div><p class=d>Year GPA ${r.yearGpa.toFixed(2)} · Cumulative GPA ${r.cumulativeGpa.toFixed(2)}</p>${r.subjects.map(s=>`<div class=row><span>${s.name}</span><span>${s.score}% · ${s.letter}</span></div>`).join('')}</div>`;}
function hsGraduationReportMarkup(r){return `<div class=card><div class=t>High school graduation report</div><p class=d>Final cumulative GPA: ${r.finalGpa.toFixed(2)} / 4.00</p>${Bar('Final GPA',r.finalGpa*25,GOLD)}<p class=d>Completed high-school years: ${r.years}</p><p class=d>Final year GPA: ${r.yearGpa.toFixed(2)}</p>${r.subjects.map(s=>`<div class=row><span>${s.name}</span><span>${s.score}% · ${s.letter}</span></div>`).join('')}<hr><div class=t>Clubs & achievements</div><p class=d>${r.club||'No club recorded'}${r.awards&&r.awards.length?' · '+r.awards.join(', '):''}</p><p class=d>${r.chosen?'College destination: '+r.chosen:'No college has been selected yet. Visit College Decisions to choose from accepted offers.'}</p></div>`;}
function hsPopupView(){const p=g.hsPopup;if(!p)return '';if(p.type==='train')return `<div class=mo><div class=ev><p><b>Sports training</b></p><p class=dd>Choose a training focus. Each session improves fitness and can improve club performance.</p><select id=hsTrainMode><option>Cardio</option><option>Weights</option><option>Strength</option></select><p class=d>Training sessions this year: ${hsEnsure().club?hsEnsure().club.trainingUses[g.age]||0:0}/3.</p><button class=ch onclick="hsDoTrain()">Complete training</button><button class=ch onclick="g.hsPopup=null;draw()">Cancel</button></div></div>`;
 if(p.type==='event'){const ev=p.data;return `<div class=mo><div class=ev><p><b>${ev.title}</b></p><p class=dd>${ev.text}</p>${ev.choices.map((x,i)=>`<button class=ch onclick="hsChooseEvent(${i})">${x.label}</button>`).join('')}</div></div>`;}
 if(p.type==='report')return `<div class=mo><div class=ev><p><b>High-school report card</b></p>${hsReportMarkup(p.data)}<button class=ch onclick="hsNextPopup()">Continue</button></div></div>`;
 if(p.type==='final-report')return `<div class=mo><div class=ev><p><b>End of high school</b></p>${hsGraduationReportMarkup(p.data)}<button class=ch onclick="hsNextPopup()">Continue</button></div></div>`;
 if(p.type==='graduation')return `<div class=mo><div class=ev><p><b>${p.title||'High school graduation'}</b></p><p class=dd>${p.text}</p><p class=d>Congratulations on completing Grade 12.</p><button class=ch onclick="hsNextPopup()">Continue</button></div></div>`;
 if(p.type==='test')return `<div class=mo><div class=ev><p><b>Take a college entrance test</b></p><p class=dd>Choose which test to take. Preparation, Smarts, IQ, GPA, and a little test-day luck affect the score.</p><button class=ch onclick="hsTakeTest('SAT')">Take the SAT</button><button class=ch onclick="hsTakeTest('ACT')">Take the ACT</button><button class=ch onclick="g.hsPopup=null;draw()">Cancel</button></div></div>`;
 if(p.type==='test-result'||p.type==='notice')return `<div class=mo><div class=ev><p><b>${p.title||'School update'}</b></p><p class=dd>${p.text||''}</p><button class=ch onclick="hsNextPopup()">${p.button||'Continue'}</button></div></div>`;
 if(p.type==='college'){const h=hsEnsure(),app=h.prep.applications.find(a=>a.name===p.name),def=HS_COLLEGES.find(c=>c.name===p.name);if(!app||!def)return `<div class=mo><div class=ev><p>Application not found.</p><button class=ch onclick="g.hsPopup=null;draw()">Close</button></div></div>`;return `<div class=mo><div class=ev><p><b>${def.name}</b></p><p class=dd>${def.desc}</p><div class=row><span>Decision</span><b>${app.status}</b></div><div class=row><span>Typical annual tuition</span><b>${loc(def.tuition)}</b></div><div class=row><span>Your GPA</span><b>${h.gpa.toFixed(2)}</b></div>${app.testScore?`<div class=row><span>${app.testType} score</span><b>${app.testScore}</b></div>`:''}${app.reason?`<p class=d>${app.reason}</p>`:''}<div class=t>Scholarships & aid</div>${app.awards&&app.awards.length?app.awards.map(a=>`<div class=row><span>${a.name}</span><span>${loc(a.amount)} / year</span></div>`).join(''):'<p class=d>No scholarship was awarded. Need-based aid is considered only after applying for financial aid and qualifying for admission.'}<div class=row><b>Total estimated annual scholarship</b><b>${loc(app.scholarship||0)}</b></div><div class=row><span>Estimated tuition after awards</span><b>${loc(Math.max(0,def.tuition-(app.scholarship||0)))}</b></div><hr>${app.status==='Accepted'&&!h.prep.chosen?`<button class=ch onclick="hsCollegeAction('${p.name}','accept')">Accept offer</button>`:''}${!h.prep.chosen&&app.status!=='Withdrawn'?`<button class=ch onclick="hsCollegeAction('${p.name}','withdraw')">Withdraw application</button>`:''}<button class=ch onclick="g.hsPopup=null;draw()">Close</button></div></div>`;}
 if(p.type==='chosen')return `<div class=mo><div class=ev><p><b>You're going to ${p.name}, next year!</b></p><p class=dd>You accepted the offer. All other college applications have been removed from your active decisions list. Your college menu will replace High School after graduation.</p><button class=ch onclick="hsNextPopup()">Continue</button></div></div>`;
 return `<div class=mo><div class=ev><p><b>${p.title||'School update'}</b></p><p class=dd>${p.text||''}</p><button class=ch onclick="hsNextPopup()">${p.button||'Continue'}</button></div></div>`;}
function hsSocialEvent(k){const socials={party:{title:'Your party takes off',text:'Friends arrive, the music is on, and you have to decide what kind of host to be.',choices:[{label:'Make everyone feel included',result:'People mixed, talked, and left with a good impression of you.',fx:{p:7},peer:5,family:1},{label:'Keep the party small and relaxed',result:'A low-key evening gave you time with close friends.',fx:{p:4},peer:4},{label:'Let things get out of hand',result:'Noise upset the household and some guests left early.',fx:{p:2,h:-2},peer:-3,family:-4}]},goParty:{title:'A party invitation',text:'A friend invites you to a party. School and family responsibilities are still on your mind.',choices:[{label:'Go for a while and be responsible',result:'You had fun, kept in touch with friends, and made it home safely.',fx:{p:5},peer:4},{label:'Stay late',result:'It was memorable, but you felt tired and less focused the next day.',fx:{p:7,h:-2},peer:3},{label:'Decline and rest',result:'You missed the party but got some rest and caught up on schoolwork.',fx:{h:2,s:1,p:0}}]},dance:{title:'Homecoming night',text:'The gym has been decorated for homecoming. Friends are taking photos and everyone is excited.',choices:[{label:'Go with friends',result:'You enjoyed the dance and strengthened friendships.',fx:{p:7},peer:5},{label:'Ask someone to dance',result:'You had a memorable conversation and grew more confident.',fx:{p:8},peer:4},{label:'Help organize the event',result:'You helped the evening run smoothly and earned school community goodwill.',fx:{p:4,s:1},teacher:2}]},prom:{title:'Prom night',text:'Prom is a major end-of-year event. You have planned your outfit, ride, and budget.',choices:[{label:'Enjoy the evening with friends',result:'You made lasting memories and celebrated the people who helped you through school.',fx:{p:8},peer:5},{label:'Go with a date',result:'You shared a special evening and got closer through honest conversation.',fx:{p:9},peer:6},{label:'Keep the plan simple',result:'You avoided extra spending and still enjoyed the evening.',fx:{p:4,m:-40},peer:2}]},ditch:{title:'Senior ditch day',text:'A group of seniors plans to skip classes together. Teachers have warned that unexcused absences can affect grades.',choices:[{label:'Join, but make up the work',result:'You had fun with friends, then caught up on the missed work.',fx:{p:5},peer:3,subject:'English',score:-2},{label:'Go to school',result:'You stayed on track and avoided attendance problems.',fx:{s:1,p:-1},subject:'History',score:2},{label:'Skip and ignore the assignments',result:'The day was fun at first, but missing work and an attendance mark hurt your record.',fx:{p:4},subject:'English',score:-8,teacher:-3}]},trip:{title:'Senior class trip',text:'Your class is planning a senior trip. Disneyland is one of the options, but the travel package costs money.',choices:[{label:'Choose Disneyland',result:'You enjoyed the rides and time with classmates. The trip was expensive but memorable.',fx:{p:9,m:-600},peer:6},{label:'Choose a lower-cost local trip',result:'You had a good time without straining your budget.',fx:{p:6,m:-120},peer:4},{label:'Skip the trip',result:'You saved your money and made plans with friends another day.',fx:{m:0,p:1}}]},play:{title:'School talent night',text:'Students are signing up for a talent show and need performers and volunteers.',choices:[{label:'Perform on stage',result:'You gained confidence and received support from classmates.',fx:{p:6,s:1},peer:3},{label:'Help backstage',result:'You helped the show succeed and worked well with others.',fx:{p:3},teacher:2,club:3},{label:'Watch from the audience',result:'You enjoyed the show without adding another commitment.',fx:{p:2}}]},volunteer:{title:'Community service day',text:'Students can volunteer at a food bank, park clean-up, or community center.',choices:[{label:'Volunteer with a group',result:'You helped the community and built connections beyond your usual circle.',fx:{p:5,s:1},peer:3},{label:'Organize the supplies',result:'You took responsibility and the group worked efficiently.',fx:{p:4,s:1},teacher:2},{label:'Use the day to study',result:'You caught up on schoolwork and reduced stress before deadlines.',fx:{s:2,p:0}}]}};const ev=socials[k];if(!ev)return;g.hsPopup={type:'event',data:ev};draw();}
function hsSocialAction(k){if(g.age<14||g.age>17)return;const fees={party:180,trip:0,prom:0,dance:0};if(k==='party'){if(g.cash<fees.party)return toast(`You need ${loc(fees.party)} to host a party.`);g.cash-=fees.party;}hsSocialEvent(k);}
function hsPrepAct(k){const h=hsEnsure(),p=h.prep;if(g.age<16)return toast('College preparation unlocks at age 16.');if(k==='sat-study'){if(p.satPrep>=3)return toast('You have completed three SAT/ACT study sessions.');p.satPrep++;g.smarts=cl(g.smarts+Math.max(1,Math.round(iqf())),0,100);g.happy=cl(g.happy-1,0,100);A({s:1,p:-1},`You completed SAT/ACT prep session ${p.satPrep}/3. The practice improved your test strategy.`);draw();return;}if(k==='research'){p.research=cl(p.research+1,0,5);hsPage='college-research';draw(1);return;}if(k==='scout'){hsPage='college-scout';draw(1);return;}if(k==='essay'){if(p.essays>=2)return toast('You have completed a draft and revision.');p.essays++;g.smarts=cl(g.smarts+1,0,100);A({p:1,s:1},p.essays===1?'You drafted a college essay about your experiences and goals.':'You revised the essay with specific examples and clearer writing.');draw();return;}if(k==='test'){if(g.age<17)return toast('The official SAT/ACT test unlocks at age 17.');g.hsPopup={type:'test'};draw();return;}if(k==='aid'){if(g.age<17)return toast('Financial aid applications unlock at age 17.');p.aidApplied=true;A({p:1},'You submitted the financial-aid forms. Need-based support will be considered for eligible offers.');draw();return;}if(k==='apply'){if(g.age<17)return toast('College applications unlock at age 17.');hsPage='college-apply';draw(1);return;}if(k==='interview'){if(g.age<17)return toast('College interviews unlock at age 17.');hsPage='college-interviews';draw(1);return;}if(k==='finish'){hsFinishApplications();return;}}
function hsScoutCollege(name){const h=hsEnsure(),p=h.prep,def=HS_COLLEGES.find(c=>c.name===name);if(!def)return;if(p.scouted.includes(name))return toast('You already scouted this campus.');if(g.cash<350)return toast(`You need ${loc(350)} to cover the visit.`);g.cash-=350;p.scouted.push(name);p.research=cl(p.research+1,0,5);g.happy=cl(g.happy+2,0,100);A({s:1,p:2},`You visited ${name}, learned about campus life, and took notes for your applications.`);draw();}
function hsApplyCollege(name){const h=hsEnsure(),p=h.prep,def=HS_COLLEGES.find(c=>c.name===name);if(!def||g.age<17||p.locked)return;if(p.applications.some(a=>a.name===name))return toast('You already applied to this college.');const fee=def.kind==='community'?0:65;if(g.cash<fee)return toast(`You need ${loc(fee)} for the application fee.`);g.cash-=fee;p.applications.push({name,status:'Pending',appliedAt:g.age,fee,reason:'Application submitted; awaiting a decision.',awards:[],scholarship:0});A({p:-1},`You submitted an application to ${name}${fee?` and paid ${loc(fee)}`:''}.`);draw();}
function hsAcademicScore(){const p=hsEnsure().prep;if(p.test==='SAT')return p.satScore||0;if(p.test==='ACT')return Math.round((p.actScore||0)*40+400);return 0;}
function hsAcceptance(def,p){const h=hsEnsure();const gpa=h.gpa,score=hsAcademicScore(),sport=h.club&&h.club.kind==='sport'?h.club.performance:0;let chance=def.base+(gpa-3)*18+(score?((score-1100)/28):def.testOptional?2:-12)+(g.smarts-50)*.16+(hsIQ()-100)*.09+p.research*1.3+p.essays*2+(p.scouted.includes(def.name)?3:0)+(p.interviews[def.name]?5:0)+(h.club?(sport>=85?7:sport>=70?4:1):0)+(h.club&&h.club.varsity?4:0);if(gpa<def.minGpa)chance-=Math.min(55,(def.minGpa-gpa)*32);if(gpa<def.minGpa-.7)chance=Math.min(chance,4);if(!def.testOptional&&!score)chance-=8;const cap={community:98,public:88,flagship:72,private:66,selective:42,ivy:25}[def.kind]||75;return cl(Math.round(Math.min(chance,cap)),1,cap);}
function hsScholarships(def,accepted){
 const h=hsEnsure(),p=h.prep,tuition=def.tuition,out=[];
 if(!accepted)return out;
 const gpa=h.gpa,iq=hsIQ(),smart=g.smarts,sport=h.club&&h.club.kind==='sport'?h.club.performance:0,varsity=!!(h.club&&h.club.varsity);
 const fullAthletic=sport>=92&&varsity,fullAcademic=gpa>=3.9&&iq>=145&&smart>=85;
 if(fullAthletic)out.push({name:'Full Athletic Scholarship',amount:tuition,why:'Varsity-level performance of 92 or higher qualified for a full-tuition athletic award.'});
 else if(fullAcademic)out.push({name:'Genius Academic Full Scholarship',amount:tuition,why:'Exceptional GPA, Smarts, and IQ qualified for a full-tuition merit award.'});
 else {
  if(gpa>=3.85)out.push({name:'Academic Merit Scholarship',amount:Math.min(tuition,Math.round(Math.max(6000,tuition*.35))),why:'A very strong GPA qualified for academic merit funding.'});
  else if(gpa>=3.6)out.push({name:'Academic Merit Scholarship',amount:Math.min(tuition,Math.round(Math.max(3000,tuition*.22))),why:'Strong grades qualified for an academic merit award.'});
  else if(gpa>=3.3)out.push({name:'Academic Achievement Grant',amount:Math.min(tuition,Math.round(Math.max(1500,tuition*.10))),why:'Good academic performance qualified for a smaller merit grant.'});
  if(sport>=86)out.push({name:'Athletic Scholarship',amount:Math.round(tuition*.70),why:'High sports performance earned a substantial athletic scholarship.'});
  else if(sport>=78)out.push({name:'Athletic Scholarship',amount:Math.round(tuition*.45),why:'Strong club performance earned an athletic scholarship.'});
  else if(sport>=68)out.push({name:'Athletic Award',amount:Math.round(tuition*.20),why:'A promising sports record earned a partial athletic award.'});
  if(p.aidApplied&&(g.cash<18000||((g.job&&g.job.pay||0)<25000))&&gpa>=def.minGpa-.25)out.push({name:'Need-Based Grant',amount:Math.round(tuition*(g.cash<3000?.42:.25)),why:'Your financial-aid application showed significant financial need and sufficient academic preparation.'});
  if(def.kind==='community'&&gpa>=2.0)out.push({name:'Community Access Grant',amount:Math.min(tuition,1500),why:'The college offered a modest access grant to help reduce first-year costs.'});
 }
 let remaining=tuition;out.forEach(a=>{a.amount=Math.min(tuition,Math.max(0,Math.round(a.amount)),remaining);remaining-=a.amount;});
 return out.filter(a=>a.amount>0);
}
function hsFinishApplications(){const h=hsEnsure(),p=h.prep;if(p.locked){hsPage='college-decisions';draw(1);return;}if(!p.applications.length)return toast('Apply to at least one college first.');if(p.research<1)return toast('Research at least one college before finishing applications.');if(p.essays<1)return toast('Write at least one college essay before submitting applications.');const nonCommunity=p.applications.some(a=>{const c=HS_COLLEGES.find(x=>x.name===a.name);return c&&!c.testOptional;});if(nonCommunity&&!p.test)return toast('Take the SAT or ACT before finalizing applications to selective colleges.');p.applications.forEach(app=>{const def=HS_COLLEGES.find(c=>c.name===app.name);if(!def||app.status!=='Pending')return;app.acceptanceChance=hsAcceptance(def,p);const accepted=ch(app.acceptanceChance);app.status=accepted?'Accepted':'Rejected';app.testType=p.test||null;app.testScore=p.test==='SAT'?p.satScore:p.test==='ACT'?p.actScore:null;const award=hsScholarships(def,accepted);app.awards=award;app.scholarship=award.reduce((a,x)=>a+x.amount,0);if(accepted){const why=[];if(h.gpa>=def.minGpa)why.push(`Your GPA of ${h.gpa.toFixed(2)} met the college's academic expectations.`);else why.push('The admission committee weighed the rest of your application despite a GPA below its typical target.');if(app.testScore)why.push(`Your ${app.testType} score was ${app.testScore}.`);if(p.essays)why.push('Your essay work strengthened the application.');if(h.club)why.push(`${h.club.name}${h.club.kind==='sport'?' performance':''} added evidence of sustained involvement.`);app.reason=why.join(' ');}else{app.reason=`The committee considered GPA (${h.gpa.toFixed(2)}), ${p.test?`${p.test} results, `:''}essays, activities, and the applicant pool. ${h.gpa<def.minGpa?'Your GPA was below this college’s typical target. ':'The applicant pool was competitive, so the full application was not enough for an offer this year. '}${def.kind==='ivy'||def.kind==='selective'?'This institution is highly selective and rejects many qualified applicants.':'Strengthening grades, test preparation, essays, or relevant activities could improve a future application.'}`;}});p.locked=true;p.decisionsDone=true;p.submittedAt=g.age;hsPage='college-decisions';g.hsPopup={type:'notice',title:'College decisions are ready',text:`You finished ${p.applications.length} college application${p.applications.length===1?'':'s'}. Open each college to review its decision, admission reasoning, scholarship awards, and estimated yearly cost.`,button:'View decisions'};draw();}
function hsCollegeAction(name,action){const h=hsEnsure(),p=h.prep,app=p.applications.find(a=>a.name===name);if(!app)return;if(action==='withdraw'){if(p.chosen)return toast('You have already accepted an offer.');app.status='Withdrawn';app.reason='You withdrew this application; it is no longer active.';g.hsPopup=null;L(`You withdrew your application to ${name}.`);draw();return;}if(action==='accept'){if(app.status!=='Accepted')return toast('Only an accepted offer can be chosen.');p.chosen=HS_COLLEGES.find(c=>c.name===name);p.applications=[app];app.chosen=true;p.locked=true;g.hsPopup={type:'chosen',name};hsPage='home';draw();}}
function hsTakeTest(which){const h=hsEnsure(),p=h.prep;if(g.age<17){g.hsPopup=null;return toast('The SAT and ACT unlock at age 17.');}const prep=p.satPrep,iq=hsIQ();if(which==='SAT'){p.satScore=cl(Math.round(900+(g.smarts-50)*5+(iq-100)*2+prep*38+(h.gpa-2)*24+R(-70,70)),400,1600);p.test='SAT';g.hsPopup={type:'test-result',title:'SAT score',text:`You scored ${p.satScore} out of 1600. Your result reflects preparation, Smarts, IQ, GPA, and test-day variation.`};}else{p.actScore=cl(Math.round(18+(g.smarts-50)*.12+(iq-100)*.05+prep*1.4+(h.gpa-2)*2+R(-3,3)),1,36);p.test='ACT';g.hsPopup={type:'test-result',title:'ACT score',text:`You scored ${p.actScore} out of 36. Your result reflects preparation, Smarts, IQ, GPA, and test-day variation.`};}draw();}
function hsInterview(name){const h=hsEnsure(),p=h.prep,app=p.applications.find(a=>a.name===name);if(!app||p.locked)return;if(p.interviews[name])return toast('You already completed this college interview.');p.interviews[name]=true;g.happy=cl(g.happy+2,0,100);A({p:2,s:1},`You completed a college interview with ${name}. A thoughtful interview may strengthen the application.`);draw();}
function hsCollegeResearch(){const h=hsEnsure(),p=h.prep;return B('Back to College Prep',"hsPage='college-prep';draw(1)")+`<div class=card><div class=t>Research colleges</div><p class=d>Compare selectivity, tuition, and entry expectations. Research improves your planning and can help you frame applications.</p><div class=row><span>Research steps completed</span><b>${p.research}/5</b></div></div>`+HS_COLLEGES.map(c=>`<div class=card><div class=t>${c.name}</div><p class=d>${c.desc}</p><div class=row><span>Estimated annual tuition</span><b>${loc(c.tuition)}</b></div><div class=row><span>Typical GPA target</span><b>${c.minGpa.toFixed(2)}+</b></div><p class=d>${c.selectivity}${c.testOptional?' · Test optional':' · SAT/ACT expected'}</p>${B('Read admissions information',`hsResearchDone('${c.name}')`)}</div>`).join('')+B('Finish research session',"hsPage='college-prep';draw(1)");}
function hsResearchDone(name){const h=hsEnsure(),p=h.prep;p.research=cl(p.research+1,0,5);L(`You researched ${name}, its costs, and typical admissions expectations.`);A({s:1,p:1},'Your college planning improved.');draw();}
function hsCollegeScout(){const h=hsEnsure(),p=h.prep;return B('Back to College Prep',"hsPage='college-prep';draw(1)")+`<div class=card><div class=t>Scout colleges</div><p class=d>Campus visits cost ${loc(350)} each in travel and meals. A visit can help you compare campus culture and demonstrate interest where appropriate.</p><p class=d>Campuses visited: ${p.scouted.length? p.scouted.join(', '):'None yet'}</p></div>`+HS_COLLEGES.map(c=>`<div class=card><div class=t>${c.name}</div><p class=d>${c.desc}</p>${B(p.scouted.includes(c.name)?'Campus scouted':`Scout campus · ${loc(350)}`,`hsScoutCollege('${c.name}')`,p.scouted.includes(c.name)||g.cash<350)}</div>`).join('');}
function hsApplyList(){const h=hsEnsure(),p=h.prep,back=B('Back to College Prep',"hsPage='college-prep';draw(1)");return back+`<div class=card><div class=t>Apply for college</div><p class=d>Choose several institutions to compare offers. Community college applications have no simulated fee; other applications cost a small fee. Do research, prepare an essay, and take an entrance test for selective institutions before finalizing.</p><div class=row><span>Applications started</span><b>${p.applications.length} / ${HS_COLLEGES.length}</b></div></div>`+HS_COLLEGES.map(c=>{const a=p.applications.find(x=>x.name===c.name);return `<div class=card><div class=t>${c.name}</div><p class=d>${c.desc}</p><div class=row><span>Annual tuition</span><b>${loc(c.tuition)}</b></div><div class=row><span>GPA target</span><b>${c.minGpa.toFixed(2)}+</b></div>${a?`<p class=d>Application status: ${a.status}</p>`:B(`Apply · ${c.kind==='community'?'No fee':loc(65)}`,`hsApplyCollege('${c.name}')`,p.locked||g.cash<(c.kind==='community'?0:65))}</div>`}).join('')+B(p.locked?'Applications finalized':'Finish applications & receive decisions',"hsFinishApplications()",p.locked||!p.applications.length||p.research<1||p.essays<1||(p.applications.some(a=>{const c=HS_COLLEGES.find(x=>x.name===a.name);return c&&!c.testOptional;})&&!p.test))+`<div class=card><div class=t>Before finalizing</div><p class=d>Research: ${p.research?'Complete':'Needed'} · Essay: ${p.essays?'Drafted':'Needed'} · SAT/ACT: ${p.test||'Not taken'} ${p.applications.some(a=>{const c=HS_COLLEGES.find(x=>x.name===a.name);return c&&!c.testOptional;})?'(required for at least one selected college)':''}</p></div>`;}
function hsInterviewsPage(){const h=hsEnsure(),p=h.prep;return B('Back to College Prep',"hsPage='college-prep';draw(1)")+`<div class=card><div class=t>College interviews</div><p class=d>Some colleges use interviews to learn about your interests, community involvement, and goals. Interviews strengthen an application modestly but do not guarantee acceptance.</p></div>`+(p.applications.length?p.applications.map(a=>B(`${a.name} <small>${p.interviews[a.name]?'Interview completed':'Practice interview'}</small>`,`hsInterview('${a.name}')`,!!p.interviews[a.name]||p.locked)).join(''):'<div class=card><p class=d>Apply to at least one college before scheduling an interview.</p></div>');}
function hsDecisions(){const h=hsEnsure(),p=h.prep;if(p.chosen)return hsCollegeChoicePage();return B('Back to High School',"hsPage='home';draw(1)")+`<div class=card><div class=t>College applications & decisions</div><p class=d>Each college lists its decision, reasons, scholarships, and estimated annual cost. Open any non-withdrawn application for full details.</p><div class=row><span>Applications</span><b>${p.applications.length}</b></div><div class=row><span>Accepted</span><b>${p.applications.filter(a=>a.status==='Accepted').length}</b></div><div class=row><span>Rejected</span><b>${p.applications.filter(a=>a.status==='Rejected').length}</b></div><div class=row><span>Withdrawn</span><b>${p.applications.filter(a=>a.status==='Withdrawn').length}</b></div></div>`+p.applications.map(a=>B(`${a.name} <small>${a.status}${a.status==='Accepted'?` · Scholarship ${loc(a.scholarship||0)}/year`:''}</small>`,`hsOpenCollege('${a.name}')`,a.status==='Withdrawn')).join('')+(p.applications.every(a=>a.status==='Rejected'||a.status==='Withdrawn')?'<div class=card><p class=d>No active offers remain. At age 18 you can still review available options; a future update can expand gap-year and transfer pathways.</p></div>':'');}
function hsOpenCollege(name){const h=hsEnsure();if(h.prep.applications.some(a=>a.name===name&&a.status!=='Withdrawn')){g.hsPopup={type:'college',name};draw();}}
function hsCollegeChoicePage(){const h=hsEnsure(),c=h.prep.chosen;if(!c)return hsDecisions();const a=h.prep.applications.find(x=>x.name===c.name);return B('Back to High School',"hsPage='home';draw(1)")+`<div class=card><div class=t>College destination</div><p class=d>You're going to ${c.name}, next year!</p><p class=d>Your accepted offer and scholarship package are saved. The College menu replaces High School after graduation.</p><div class=row><span>Annual tuition</span><b>${loc(c.tuition)}</b></div><div class=row><span>Scholarships per year</span><b>${loc(a&&a.scholarship||0)}</b></div><div class=row><span>Estimated tuition after awards</span><b>${loc(Math.max(0,c.tuition-(a&&a.scholarship||0)))}</b></div>${a&&a.awards?a.awards.map(x=>`<div class=row><span>${x.name}</span><span>${loc(x.amount)}/year</span></div>`).join(''):''}</div>`;}
function hsCollegePrep(){const h=hsEnsure(),p=h.prep;const testStatus=p.test==='SAT'?`SAT ${p.satScore}/1600`:p.test==='ACT'?`ACT ${p.actScore}/36`:'Not taken';return B('Back to High School',"hsPage='home';draw(1)")+`<div class=card><div class=t>College Prep · Age ${g.age}</div><p class=d>Build a balanced application: prepare for entrance tests, research and visit campuses, write essays, apply for aid, interview, and compare decisions. GPA, Smarts, IQ, test scores, school involvement, and sports performance all contribute.</p>${Bar('Cumulative GPA',h.gpa*25,GOLD)}<div class=row><span>GPA</span><b>${h.gpa.toFixed(2)}</b></div><div class=row><span>SAT/ACT prep sessions</span><b>${p.satPrep}/3</b></div><div class=row><span>Research points</span><b>${p.research}/5</b></div><div class=row><span>College essay drafts/revisions</span><b>${p.essays}/2</b></div><div class=row><span>Test score</span><b>${testStatus}</b></div><div class=row><span>Financial aid</span><b>${p.aidApplied?'Applied':'Not applied'}</b></div></div>`+B(`Study for SAT/ACT <small>${p.satPrep}/3 sessions · age 16+</small>`,`hsPrepAct('sat-study')`,p.satPrep>=3)+B(`Research colleges <small>${p.research}/5 research points</small>`,`hsPrepAct('research')`,false)+B(`Scout colleges <small>${p.scouted.length} campus visits</small>`,`hsPrepAct('scout')`,false)+B(`Write college essays <small>${p.essays}/2 drafts or revisions</small>`,`hsPrepAct('essay')`,p.essays>=2)+B(`Take SAT/ACT <small>${p.test?testStatus:'Unlocks at age 17'}</small>`,`hsPrepAct('test')`,g.age<17)+B(`Apply for college <small>${p.applications.length} application${p.applications.length===1?'':'s'}</small>`,`hsPrepAct('apply')`,g.age<17||p.locked)+B(`Apply for financial aid <small>${p.aidApplied?'Submitted':'Unlocks at age 17'}</small>`,`hsPrepAct('aid')`,g.age<17||p.aidApplied)+B(`College interviews <small>${Object.keys(p.interviews).filter(k=>p.interviews[k]).length} completed</small>`,`hsPrepAct('interview')`,g.age<17||!p.applications.length||p.locked)+(p.applications.length?B('Review college decisions',"hsPage='college-decisions';draw(1)",!p.locked):'')+`<div class=card><div class=t>Suggested order</div><p class=d>1. Study and research at age 16. 2. Scout campuses and draft/revise essays. 3. At age 17, take the SAT or ACT, submit college applications and financial-aid forms, and complete interviews. 4. Finalize applications to receive decisions, then accept an offer.</p></div>`;}
function hsSocialPage(){const h=hsEnsure(),club=h.club;return B('Back to High School',"hsPage='home';draw(1)")+`<div class=card><div class=t>Social activities</div><p class=d>Social choices affect happiness and friendships, but some have costs or can affect health, family trust, attendance, and grades. Activities unlock at realistic high-school ages.</p></div>`+B(`Throw a party <small>Age 14+ · costs ${loc(180)}</small>`,'hsSocialAction(\'party\')',g.cash<180)+B('Go to a party <small>Age 14+</small>',"hsSocialAction('goParty')",g.age<14)+B('Go to homecoming <small>Ages 14–15</small>',"hsSocialAction('dance')",g.age<14||g.age>15)+B('Go to prom <small>Ages 16–17</small>',"hsSocialAction('prom')",g.age<16||g.age>17)+B('Senior ditch day <small>Age 17 · attendance and grade risk</small>',"hsSocialAction('ditch')",g.age!==17)+B('Senior trip · Disneyland or local trip <small>Age 17</small>',"hsSocialAction('trip')",g.age!==17)+B('School talent night <small>Age 14+</small>',"hsSocialAction('play')",g.age<14)+B('Community service day <small>Age 14+</small>',"hsSocialAction('volunteer')",g.age<14)+B('Join a study group <small>Improve class progress and friendships</small>',"hsSocialAction('studyGroup')",false)+B('Volunteer at a school event <small>Build school community</small>',"hsSocialAction('schoolEvent')",false);}
function hsSocialEvent(k){if(k==='studyGroup'){const h=hsEnsure();HS_SUBJECTS.forEach(s=>h.current.subjects[s].score=cl(h.current.subjects[s].score+3,0,100));const peer=P(h.classmates);peer.bond=cl(peer.bond+4,0,100);hsRecalcGPA();A({s:2,p:3},'You joined a study group, made progress across subjects, and spent time with classmates.');draw();return;}if(k==='schoolEvent'){const h=hsEnsure();h.teacher.bond=cl(h.teacher.bond+3,0,100);if(h.club)h.club.performance=cl(h.club.performance+2,0,100);A({p:3,s:1},'You volunteered at a school event and helped the school community.');draw();return;}const socials={party:{title:'Your party takes off',text:'Friends arrive, the music is on, and you have to decide what kind of host to be.',choices:[{label:'Make everyone feel included',result:'People mixed, talked, and left with a good impression of you.',fx:{p:7},peer:5,family:1},{label:'Keep the party small and relaxed',result:'A low-key evening gave you time with close friends.',fx:{p:4},peer:4},{label:'Let things get out of hand',result:'Noise upset the household and some guests left early.',fx:{p:2,h:-2},peer:-3,family:-4}]},goParty:{title:'A party invitation',text:'A friend invites you to a party. School and family responsibilities are still on your mind.',choices:[{label:'Go for a while and be responsible',result:'You had fun, kept in touch with friends, and made it home safely.',fx:{p:5},peer:4},{label:'Stay late',result:'It was memorable, but you felt tired and less focused the next day.',fx:{p:7,h:-2},peer:3},{label:'Decline and rest',result:'You missed the party but got some rest and caught up on schoolwork.',fx:{h:2,s:1,p:0}}]},dance:{title:'Homecoming night',text:'The gym has been decorated for homecoming. Friends are taking photos and everyone is excited.',choices:[{label:'Go with friends',result:'You enjoyed the dance and strengthened friendships.',fx:{p:7},peer:5},{label:'Ask someone to dance',result:'You had a memorable conversation and grew more confident.',fx:{p:8},peer:4},{label:'Help organize the event',result:'You helped the evening run smoothly and earned school community goodwill.',fx:{p:4,s:1},teacher:2}]},prom:{title:'Prom night',text:'Prom is a major end-of-year event. You have planned your outfit, ride, and budget.',choices:[{label:'Enjoy the evening with friends',result:'You made lasting memories and celebrated the people who helped you through school.',fx:{p:8},peer:5},{label:'Go with a date',result:'You shared a special evening and got closer through honest conversation.',fx:{p:9},peer:6},{label:'Keep the plan simple',result:'You avoided extra spending and still enjoyed the evening.',fx:{p:4,m:-40},peer:2}]},ditch:{title:'Senior ditch day',text:'A group of seniors plans to skip classes together. Teachers have warned that unexcused absences can affect grades.',choices:[{label:'Join, but make up the work',result:'You had fun with friends, then caught up on the missed work.',fx:{p:5},peer:3,subject:'English',score:-2},{label:'Go to school',result:'You stayed on track and avoided attendance problems.',fx:{s:1,p:-1},subject:'History',score:2},{label:'Skip and ignore the assignments',result:'The day was fun at first, but missing work and an attendance mark hurt your record.',fx:{p:4},subject:'English',score:-8,teacher:-3}]},trip:{title:'Senior class trip',text:'Your class is planning a senior trip. Disneyland is one of the options, but the travel package costs money.',choices:[{label:'Choose Disneyland',result:'You enjoyed the rides and time with classmates. The trip was expensive but memorable.',fx:{p:9,m:-600},peer:6},{label:'Choose a lower-cost local trip',result:'You had a good time without straining your budget.',fx:{p:6,m:-120},peer:4},{label:'Skip the trip',result:'You saved your money and made plans with friends another day.',fx:{m:0,p:1}}]},play:{title:'School talent night',text:'Students are signing up for a talent show and need performers and volunteers.',choices:[{label:'Perform on stage',result:'You gained confidence and received support from classmates.',fx:{p:6,s:1},peer:3},{label:'Help backstage',result:'You helped the show succeed and worked well with others.',fx:{p:3},teacher:2,club:3},{label:'Watch from the audience',result:'You enjoyed the show without adding another commitment.',fx:{p:2}}]},volunteer:{title:'Community service day',text:'Students can volunteer at a food bank, park clean-up, or community center.',choices:[{label:'Volunteer with a group',result:'You helped the community and built connections beyond your usual circle.',fx:{p:5,s:1},peer:3},{label:'Organize the supplies',result:'You took responsibility and the group worked efficiently.',fx:{p:4,s:1},teacher:2},{label:'Use the day to study',result:'You caught up on schoolwork and reduced stress before deadlines.',fx:{s:2,p:0}}]}};const ev=socials[k];if(!ev)return;g.hsPopup={type:'event',data:ev};draw();}
function hsCollegePlaceholder(){const h=hsEnsure(),c=h.prep.chosen,app=c&&h.prep.applications.find(a=>a.name===c.name);return `<div class=card><div class=t>${c?c.name:'College'}</div><p class=d>${c?`Enrolled for next year. This is the college menu placeholder for the next update.`:'You have graduated high school. Choose an accepted offer from College Decisions or explore admissions options.'}</p>${c?`<div class=row><span>Annual tuition</span><b>${loc(c.tuition)}</b></div><div class=row><span>Scholarship package</span><b>${loc(app&&app.scholarship||0)} / year</b></div><div class=row><span>Estimated tuition after awards</span><b>${loc(Math.max(0,c.tuition-(app&&app.scholarship||0)))}</b></div><p class=d>Your enrollment is saved. Campus life, classes, majors, and college housing will be expanded in the next update.</p>`:B('College decisions',"wsel='hsgraduate';hsPage='college-decisions';draw(1)")}</div>`;}
function hsGraduateP(){const h=hsEnsure();return `<div class=card><div class=t>High School Graduate</div><p class=d>You completed Grade 12. Your final GPA is ${h.gpa.toFixed(2)}. Choose an accepted college offer to set your destination, or review your college decisions.</p></div>`+(h.prep.chosen?B(`College · ${h.prep.chosen.name}`,"wsel='college';draw(1)"):B('College decisions',"hsPage='college-decisions';draw(1)",!h.prep.applications.length||!h.prep.locked))+B('View final report card',`hsShowReport(${h.years.length?h.years[h.years.length-1].year:17})`,!h.years.length);}
function highSchoolP(){const h=hsEnsure(),grade=cl(g.age-5,9,12),back=B('Back to High School',"hsPage='home';hsSelectedPeer=null;draw(1)");if(g.age>=18){if(hsPage==='college-decisions')return hsDecisions();if(hsPage==='college-choice')return hsCollegeChoicePage();if(hsPage==='grades')return hsGrades();return hsGraduateP();}
 if(hsPage==='grades')return hsGrades();if(hsPage==='teacher')return back+`<div class=card><div class=t>Teacher · ${h.teacher.n}</div><p class=d>Ask questions, discuss feedback, and attend office hours. You can use three teacher interactions each school year.</p>${Bar('Relationship',h.teacher.bond,rc(h.teacher.bond))}</div>`+HS_TEACHER_ACTIONS.map((a,i)=>B(`${a[0]} <small>Relationship +${a[1]} · learning support</small>`,`hsTeacherAct(${i})`,(h.current.teacherUsed||0)>=3)).join('');
 if(hsPage==='studies')return back+`<div class=card><div class=t>Studies · Grade ${grade}</div><p class=d>Complete homework, prepare for exams, take tests, and submit projects. You can study each subject twice each year. Strong Smarts and IQ support higher marks.</p>${Bar('Class focus',h.focus,GOLD)}${B(h.current.attended?'Class attendance recorded':'Attend class & take notes <small>Small progress across every subject</small>','hsAttend()',h.current.attended)}</div>`+HS_SUBJECTS.map(s=>{const c=h.current.subjects[s],t=c.tasks,score=hsSubjectScore(s);return `<div class=card><div class=row><span class=t>${s}</span><span class=d>${score}% · ${hsLetter(score)}</span></div>${Bar('Current mark',score,s==='PE'?'#4FB39A':'#6FA8DC')}<div class=d>Core assignments</div>${B(`Study ${s} <small>${t.study}/2 sessions</small>`,`hsTask('${s}','study')`,t.study>=2)}${B(`Do ${s} homework <small>${t.homework?'Completed':'Required'}</small>`,`hsTask('${s}','homework')`,t.homework)}${B(`Prepare for ${s} exam <small>${t.prepare?'Prepared':'Study guide'}</small>`,`hsTask('${s}','prepare')`,t.prepare)}${B(`Take ${s} exam <small>${t.exam?'Completed':t.prepare?'Ready':'Prepare first'}</small>`,`hsTask('${s}','exam')`,t.exam||!t.prepare)}${B(`Complete a ${s} project <small>${t.project?'Turned in':'Required'}</small>`,`hsTask('${s}','project')`,t.project)}<hr><div class=d>Subject-specific practice</div>${(HS_SPECIAL_ACTS[s]||[]).map((a,i)=>B(`${a[0]} <small>Practice and participation</small>`,`hsSpecial('${s}',${i})`,t.special)).join('')}</div>`}).join('');
 if(hsPage==='classmates'){const peer=hsSelectedPeer?hsPeer(hsSelectedPeer):null;if(peer){const used=peer.used[g.age]||0;return B('Back to Classmates',"hsSelectedPeer=null;draw(1)")+`<div class=card><div class=t>${peer.n}</div><p class=d>Classmate · Age ${peer.age}${peer.friendId?' · In your Friends list':''}</p>${Bar('Relationship',peer.bond,rc(peer.bond))}<p class=d>Talk, work together, and share notes to build trust. Ask to be friends when the relationship reaches 75.</p></div>`+HS_PEER_ACTIONS.map((a,i)=>B(`${a[0]} <small>Relationship +${a[1]}</small>`,`hsPeerAct('${peer.id}',${i})`,used>=3)).join('')+B(peer.friendId?'Already friends':'Ask to be friends <small>Requires relationship 75+</small>',`hsMakeFriend('${peer.id}')`,!!peer.friendId||peer.bond<75);}return back+`<div class=card><div class=t>Classmates</div><p class=d>These classmates stay in your high-school group and can become Friends in Relationships when your bond reaches 75 and they accept.</p></div>`+h.classmates.map(c=>`<div class=card onclick="hsSelectedPeer='${c.id}';draw(1)"><div class=row><span class=t>${c.n}</span><span class=d>${c.friendId?'Friend':'Classmate'} · Age ${c.age}</span></div>${Bar('Relationship',c.bond,rc(c.bond))}<p class=d>Tap to interact</p></div>`).join('');}
 if(hsPage==='social')return hsSocialPage();if(hsPage==='club-list')return hsClubList();if(hsPage==='club')return hsClubView();if(hsPage==='college-prep')return hsCollegePrep();if(hsPage==='college-research')return hsCollegeResearch();if(hsPage==='college-scout')return hsCollegeScout();if(hsPage==='college-apply')return hsApplyList();if(hsPage==='college-interviews')return hsInterviewsPage();if(hsPage==='college-decisions')return hsDecisions();if(hsPage==='positions'){const d=hsClubDef(hsSelectedClub);if(!d)return hsClubList();return back+`<div class=card><div class=t>Choose your ${d.name} position</div><p class=d>Your position is saved for this club until you quit.</p></div>`+(d.positions||['Member']).map(pos=>B(pos,`hsJoinClub('${d.name}','${pos}')`)).join('');}
 if(hsPage==='college-choice')return hsCollegeChoicePage();
 const current=h.current,done=HS_SUBJECTS.reduce((n,s)=>{const t=current.subjects[s].tasks;return n+(t.study?1:0)+(t.homework?1:0)+(t.prepare?1:0)+(t.exam?1:0)+(t.project?1:0)},0),max=HS_SUBJECTS.length*5;
 let out=`<div class=card><div class=t>High School · Grade ${grade}</div><p class=d>Age ${g.age} · Grades 9–12. Math, Science, English, History, and PE. Your tasks, study habits, Smarts, IQ, and involvement shape your GPA and future options.</p>${Bar('Cumulative GPA',h.gpa*25,GOLD)}<div class=row><span>GPA</span><b>${h.gpa.toFixed(2)} / 4.00</b></div><p class=d>Core assignments recorded this year: ${done}/${max} · Teacher relationship ${h.teacher.bond}/100</p></div>${B(`GPA & Grades <small>${h.gpa.toFixed(2)} / 4.00 · report cards each year</small>`,"hsPage='grades';draw(1)")}`;
 if(h.club)out+=B(`${h.club.name}${h.club.kind==='sport'?' · '+(h.club.varsity?'Varsity':'Junior Varsity'):''} <small>${h.club.kind==='sport'?`Position: ${h.club.position} · performance ${Math.round(h.club.performance)}/100`:`Club performance ${Math.round(h.club.performance)}/100`}</small>`,"hsPage='club';draw(1)");out+='<hr>';
 out+=B(`Teacher <small>${h.teacher.n} · relationship ${Math.round(h.teacher.bond)}/100</small>`,"hsPage='teacher';draw(1)")+B('Studies <small>Math, Science, English, History, PE</small>',"hsPage='studies';draw(1)")+B(`Classmates <small>${h.classmates.length} students · Friends threshold 75</small>`,"hsPage='classmates';draw(1)")+B('Social activities <small>Parties, dances, senior events, and more</small>',"hsPage='social';draw(1)");if(!h.club)out+=B('Join a club <small>Sports, arts, academics, leadership, and wellness</small>',"hsPage='club-list';draw(1)");
 if(h.prep.chosen)out+=B(`College · ${h.prep.chosen.name} <small>Accepted offer · ${loc((h.prep.applications.find(a=>a.name===h.prep.chosen.name)||{}).scholarship||0)} scholarship/year</small>`,"hsPage='college-choice';draw(1)");else if(h.prep.locked)out+=B('College Decisions <small>Review acceptances, rejections, and scholarships</small>',"hsPage='college-decisions';draw(1)");else if(g.age>=16)out+=B('College Prep <small>Test preparation, research, essays, applications, and aid</small>',"hsPage='college-prep';draw(1)");return out;}
