function collegeRequirements(level){const d=COLLEGE_LEVELS[level]||COLLEGE_LEVELS.university;return {credits:d.credits,ge:d.ge,major:d.major,minor:d.minor,gpa:['law','medical','dental','vet'].includes(level)?3:level==='ivy'?2.5:2,years:d.years};}
function collegeEnsure(){if(!g.collegeTrack)g.collegeTrack={applications:[],current:null,degrees:[],prep:{tests:{},research:0},aidHistory:[],nextId:1};const t=g.collegeTrack;t.applications=Array.isArray(t.applications)?t.applications:[];t.degrees=Array.isArray(t.degrees)?t.degrees:[];t.aidHistory=Array.isArray(t.aidHistory)?t.aidHistory:[];t.prep=t.prep||{tests:{},research:0};t.prep.tests=t.prep.tests||{};if(t.current){const c=t.current;c.credits=c.credits||{ge:0,major:0,minor:0};c.requirements=c.requirements||collegeRequirements(c.level);c.actions=c.actions||{};c.yearActions=c.yearActions||{};c.years=c.years||[];c.schedule=c.schedule||[];c.peers=c.peers||[];c.professors=c.professors||[];c.aid=c.aid||{scholarship:0,grant:0,loan:0,parents:0};c.aidBreakdown=c.aidBreakdown||[];c.year=Number(c.year)||1;if(!c.rosterMade){for(let i=0;i<6;i++)c.peers.push({id:'cp'+Math.random().toString(36).slice(2,8),name:nm2(),bond:R(25,60),friend:false,used:{}});for(let i=0;i<3;i++)c.professors.push({id:'pr'+Math.random().toString(36).slice(2,8),name:nm2(),bond:R(30,58),used:{}});c.rosterMade=true;}}return t;}
function collegeCurrentFrom(name,level,major,minor,meta={}){const d=COLLEGE_LEVELS[level]||COLLEGE_LEVELS.university,t=collegeEnsure();t.current={name,level,major:major||'Undeclared',minor:minor||'None',year:1,yearsElapsed:0,performance:cl(35+(g.smarts||50)*.25+(Number(g.iq)||100)*.08,20,70),gpa:0,credits:{ge:0,major:0,minor:0},requirements:collegeRequirements(level),schedule:[],yearActions:{},years:[],aid:{scholarship:0,grant:0,loan:0,parents:0},aidBreakdown:[],tuition:meta.tuition||d.tuition,room:14500,books:1200,fees:900,applicationId:meta.applicationId||null,club:null,fraternity:null,rushTried:{},lastEventYear:-1};collegeEnsure();return t.current;}
function collegeCanAccess(level){const t=collegeEnsure(),d=t.degrees,has=x=>d.some(a=>a.level===x),b=d.filter(a=>a.level==='bachelor').slice(-1)[0],major=b&&b.major||'';if(level==='community')return !has('community');if(level==='trade')return !has('trade');if(level==='university'||level==='ivy')return !has('bachelor')&&!has('master');if(level==='masters')return has('bachelor')&&!has('master');if(level==='law')return has('bachelor')&&/political|history|english|criminal|law|economics/i.test(major)&&!!t.prep.tests.LSAT;if(level==='medical')return has('bachelor')&&/biology|chemistry|nursing|pre-med/i.test(major)&&!!t.prep.tests.MCAT;if(level==='dental')return has('bachelor')&&/biology|chemistry|pre-med|nursing/i.test(major)&&!!t.prep.tests.DAT;if(level==='vet')return has('bachelor')&&/biology|veterinary|animal|pre-med|chemistry/i.test(major)&&!!t.prep.tests.GRE;if(level==='other')return has('master');return true;}
function collegeGroupsAvailable(){const d=collegeEnsure().degrees;if(d.some(x=>x.level==='master'))return ['law','medical','dental','vet','other'];if(d.some(x=>x.level==='bachelor'))return ['masters'];const a=['community','university','ivy','trade'];if(d.some(x=>x.level==='community'))return a.filter(x=>x!=='community');if(d.some(x=>x.level==='trade'))return a.filter(x=>x!=='trade');return a;}
function collegeAcademicGpa(){const t=collegeEnsure(),d=t.degrees.slice(-1)[0];if(d)return d.gpa;if(t.current)return t.current.gpa;const h=g.highSchool;return h&&h.gpa!=null?h.gpa:(g.gpa||0);}
function collegeAdmissionOdds(level,row){const t=collegeEnsure(),hs=g.highSchool,gpa=collegeAcademicGpa(),req=collegeRequirements(level);const hsPrep=g.highSchool&&g.highSchool.prep||{};let score=(gpa/4)*36+(g.smarts||50)*.12+((Number(g.iq)||100)-80)*.13+(g.fit||50)*.05+((t.prep.research||0)+(hsPrep.research||0))*1.4+((hsPrep.essays||0)*2)+((hsPrep.scouted||[]).length*1.2)+((t.prep.tests.SAT||0)||hsPrep.satScore||0)/1600*8+((t.prep.tests.ACT||0)||hsPrep.actScore||0)/36*8;const b=t.degrees.filter(d=>d.level==='bachelor').slice(-1)[0];if(['law','medical','dental','vet','other','masters'].includes(level)&&b)score+=12;return cl(Math.round(row[1]*100+(score-48)*.62),2,level==='ivy'?42:['medical','dental','vet','law'].includes(level)?60:98);}
function collegeSelectGroup(group){collegeGroup=group;collegePage='list';collegeSelected='';draw(1)}
function collegeSelectSchool(name){collegeSelected=name;collegeMajor='Undeclared';collegeMinor='None';collegePage='detail';draw(1)}
function collegeGroupList(){return B('Back to College',"collegePage='home';draw(1)")+`<div class=card><div class=t>${COLLEGE_LEVELS[collegeGroup].label}</div><p class=d>Compare acceptance rates, tuition, and popular programs. Previous degrees and entrance exams may be required.</p></div>`+(COLLEGE_GROUPS[collegeGroup]||[]).map(r=>{const app=collegeEnsure().applications.find(a=>a.name===r[0]&&a.level===collegeGroup);return `<div class=card><div class=row><span class=t>${r[0]}</span><span class=d>${Math.round(r[1]*100)}% acceptance</span></div><p class=d>${r[3]}</p><div class=row><span>Annual tuition</span><b>${collegeLoc(r[2])}</b></div>${app?`<p class=d>Application: ${app.status}</p>`:B('View college information',`collegeSelectSchool('${r[0]}')`,!collegeCanAccess(collegeGroup))}</div>`}).join('')+(collegeCanAccess(collegeGroup)?'':`<div class=card><p class=d>Entry requirements are not yet met. ${collegeGroup==='law'?'Law requires a relevant bachelor’s and LSAT.':collegeGroup==='medical'?'Medicine requires a science-related bachelor’s and MCAT.':collegeGroup==='dental'?'Dentistry requires a science-related bachelor’s and DAT.':collegeGroup==='vet'?'Veterinary school requires a related bachelor’s and GRE.':collegeGroup==='masters'?'Complete a bachelor’s degree first.':'Complete the required previous degree and entrance exam first.'}</p></div>`)}
function collegeDetail(){const r=(COLLEGE_GROUPS[collegeGroup]||[]).find(x=>x[0]===collegeSelected);if(!r)return collegeGroupList();const level=collegeGroup,d=COLLEGE_LEVELS[level],req=collegeRequirements(level),odds=collegeAdmissionOdds(level,r);return B('Back to college list',"collegePage='list';draw(1)")+`<div class=card><div class=t>${r[0]}</div><p class=d>${r[3]}</p><div class=row><span>Acceptance rate</span><b>${Math.round(r[1]*100)}%</b></div><div class=row><span>Annual tuition</span><b>${collegeLoc(r[2])}</b></div><div class=row><span>Program length</span><b>${d.years} years</b></div><div class=row><span>Your latest GPA</span><b>${collegeAcademicGpa().toFixed(2)}</b></div><div class=row><span>Sports / extracurricular profile</span><b>${collegeFindSport()?`${Math.round(collegeFindSport().performance)}/100${collegeFindSport().varsity?' · Varsity':''}`:'General activities'}</b></div><div class=row><span>Estimated acceptance odds</span><b>${odds}%</b></div><div class=t>Choose your program</div><label class=d>Major</label><select id=collegeMajorSelect onchange="collegeMajor=this.value">${COLLEGE_MAJORS.map(m=>`<option${m===collegeMajor?' selected':''}>${m}</option>`).join('')}</select><label class=d>Minor</label><select id=collegeMinorSelect onchange="collegeMinor=this.value">${COLLEGE_MINORS.map(m=>`<option${m===collegeMinor?' selected':''}>${m}</option>`).join('')}</select><p class=d>Admission odds reflect GPA, Smarts, IQ, entrance tests, prior study, and selectivity. Acceptance is not guaranteed.</p>${B('Apply to this college',`collegeApply('${level}','${r[0]}',${r[1]},${r[2]})`,!collegeCanAccess(level))}</div>`;}
function collegeEducationView(){const t=collegeEnsure();if(t.current)return collegeCurrentPage();if(collegePage==='list')return collegeGroupList();if(collegePage==='detail')return collegeDetail();if(collegePage==='prep')return collegePrepPage();return `<div class=card><div class=t>College & Higher Education</div><p class=d>Choose a program. Completed degrees remain on your record. Only one program can be active at a time.</p>${t.degrees.length?t.degrees.map(d=>`<div class=row><span>${d.title}</span><b>GPA ${d.gpa.toFixed(2)}</b></div>`).join(''):''}</div>`+collegeGroupsAvailable().map(k=>B(`${COLLEGE_LEVELS[k].label} <small>${COLLEGE_LEVELS[k].years} years · ${collegeLoc(COLLEGE_LEVELS[k].tuition)}/year</small>`,`collegeSelectGroup('${k}')`,!collegeCanAccess(k))).join('')+B('College Prep & entrance exams',"collegePage='prep';draw(1)")+`<div class=card><p class=d>Typical program lengths: associate/trade 2 years, bachelor’s 4, master’s 2, JD 3, and MD/DDS/DVM 4 years.</p></div>`;}
function collegeApply(level,name,rate,tuition){const t=collegeEnsure();if(!collegeCanAccess(level)){g.hsPopup={type:'college-notice',title:'Entry requirements not met',text:'Complete the required prior degree and entrance exam before applying.'};draw();return;}if(t.applications.some(a=>a.name===name&&a.level===level))return toast('You already applied to this program.');const odds=collegeAdmissionOdds(level,[name,rate,tuition,'']),accepted=Math.random()*100<odds,sport=collegeFindSport(),awards=[];let scholarship=accepted?Math.min(tuition,Math.round(tuition*cl((g.smarts/100)*.18+((g.highSchool&&g.highSchool.gpa||g.gpa||0)/4)*.20,0,.35))):0;if(accepted&&scholarship)awards.push({name:'Academic merit scholarship',amount:scholarship});if(accepted&&sport&&sport.performance>=70&&['university','ivy','masters'].includes(level)){const athletic=Math.min(tuition-scholarship,Math.round(tuition*cl((sport.performance-60)/40,0,1)));if(athletic){awards.push({name:`Athletic scholarship · ${sport.name}`,amount:athletic});scholarship+=athletic;}}scholarship=Math.min(tuition,scholarship);const app={id:'app'+(t.nextId++),name,level,major:collegeMajor,minor:collegeMinor,status:accepted?'Accepted':'Rejected',odds,tuition,scholarship,awards,reason:accepted?`Accepted with estimated odds of ${odds}%. Academic preparation and overall profile supported your application.`:`Rejected. Selectivity, academic preparation, or program prerequisites may have limited your application.`,aidApplied:false,aid:0,createdAge:g.age};t.applications.push(app);collegeSelected=name;collegePage='application';g.hsPopup={type:'college-result',appId:app.id};draw();}
function collegeFindSport(){const h=g.highSchool||{},m=g.middle||{},c=(h.club&&h.club.kind==='sport'?h.club:null)||(m.club&&m.club.kind==='sport'?m.club:null);return c?{name:c.name,performance:Number(c.performance)||0,position:c.position||'Athlete',varsity:!!c.varsity}:null;}
function collegeAppById(id){return collegeEnsure().applications.find(a=>a.id===id)}
function collegeWithdrawApplication(id){const a=collegeAppById(id);if(!a)return;a.status='Withdrawn';a.reason='You withdrew this application; it is no longer active.';g.hsPopup=null;collegePage='list';draw();}
function collegeAidApply(id){const t=collegeEnsure(),a=collegeAppById(id);if(!a||a.status!=='Accepted')return;if(a.aidApplied)return toast('Financial aid has already been calculated for this application.');const low=(g.cash||0)<Math.max(15000,a.tuition*.5),gpa=collegeAcademicGpa(),max=a.tuition;let grant=0,loan=0,parent=0,awards=[];if(gpa>=3.5){grant=Math.min(max*.35,Math.round(max*.25+(gpa-3.5)*max*.12));awards.push({name:'Academic grant',amount:grant});}if(g.smarts>=90&&(Number(g.iq)||100)>=135&&gpa>=3.7){const genius=Math.max(0,max-a.scholarship-grant);grant+=genius;awards.push({name:'Genius full-tuition award',amount:genius});}if(low&&gpa>=2.5){const need=Math.min(max*.35,Math.round(max*.25));grant+=need;awards.push({name:'Need-based grant',amount:need});loan=Math.min(max*.25,Math.round(max*.15));if(loan)awards.push({name:'Federal student loan',amount:loan});}grant=Math.min(grant,Math.max(0,max-a.scholarship));loan=Math.min(loan,Math.max(0,max-a.scholarship-grant));if(g.family&&g.family.wealth>1){parent=Math.min(max*.2,Math.round(max*.08));awards.push({name:'Family contribution',amount:parent});}parent=Math.min(parent,Math.max(0,max-a.scholarship-grant-loan));a.aid=Math.min(max,grant+loan+parent);a.aidBreakdown=awards;a.aidApplied=true;a.aidAmounts={grant,loan,parent};t.aidHistory.push({college:a.name,awards:awards.slice(),total:a.aid});g.hsPopup={type:'college-aid-result',appId:id};draw();}
function collegeStart(id){const t=collegeEnsure(),a=collegeAppById(id);if(!a||a.status!=='Accepted')return;t.applications=[a];collegeCurrentFrom(a.name,a.level,a.major,a.minor,{applicationId:a.id,tuition:a.tuition});const c=t.current;c.aid.scholarship=a.scholarship;c.aidBreakdown=(a.awards||[]).slice();if(a.aidApplied&&a.aidAmounts){c.aid.grant=a.aidAmounts.grant||0;c.aid.loan=a.aidAmounts.loan||0;c.aid.parents=a.aidAmounts.parent||0;c.aidBreakdown=c.aidBreakdown.concat(a.aidBreakdown||[]);}const sport=collegeFindSport();if(sport&&(a.awards||[]).some(x=>x.name.startsWith('Athletic'))){c.club={name:sport.name,kind:'sport',performance:sport.performance,position:sport.position,actions:{},trainUsed:{},workoutUsed:{},team:[],coach:{name:nm2(),bond:55}};}collegePage='current';wsel='college';wsub=null;tab='Work';g.edu=Math.max(g.edu||0,1);A({p:4,s:1},`You enrolled at ${a.name} to study ${a.major}.`);draw(1);}
function collegeResultPopup(){const a=collegeAppById(g.hsPopup.appId);if(!a)return '';return `<div class=mo><div class=ev><p><b>${a.status==='Accepted'?'College acceptance!':'College application result'}</b></p><p class=dd>${a.name}</p><p>${a.reason}</p><div class=row><span>Major / minor</span><b>${a.major} / ${a.minor}</b></div><div class=row><span>Estimated admission odds</span><b>${a.odds}%</b></div><div class=row><span>Annual tuition</span><b>${collegeLoc(a.tuition)}</b></div>${(a.awards||[]).map(x=>`<div class=row><span>${x.name}</span><b>${collegeLoc(x.amount)}</b></div>`).join('')}${a.status==='Accepted'?`<button class=ch onclick="g.hsPopup=null;collegeStart('${a.id}')">Start college</button><button class=ch onclick="collegeAidApply('${a.id}')">Apply for financial aid</button><button class=ch onclick="collegeWithdrawApplication('${a.id}')">Withdraw application</button>`:''}<button class=ch onclick="g.hsPopup=null;collegePage='home';draw()">Continue</button></div></div>`;}
